LAMBDA = 50.0
# the system's matrix: eigenvalues -1 (along (1, 1)) and -1000 (along (1, -1))
A_SYS = [[-500.5, 499.5], [499.5, -500.5]]

#| One step of $y' = -\lambda y$ with $\lambda$ = LAMBDA. As written it is forward
#| Euler. Make it backward Euler: $y_{n+1} = y_n + h f(y_{n+1})$.
def decay_step(y, h) {
    return y + h * (-LAMBDA * y)
}

#| One step of $y' = Ay$ for the 2 by 2 matrix A_SYS, returning the new y. As
#| written it is forward Euler. Make it backward Euler: solve $(I - hA)\,y_{n+1} = y_n$.
def system_step(y: Arr, h) {
    y_new = zeros(2)
    for i to 2 {
        y_new[i] = y[i] + h * (A_SYS[i, 0] * y[0] + A_SYS[i, 1] * y[1])
    }
    return y_new
}

# A_SYS (1, 1) = -(1, 1) and A_SYS (1, -1) = -1000 (1, -1): its two rates
slow_rate = A_SYS[0, 0] + A_SYS[0, 1]
fast_rate = A_SYS[0, 0] - A_SYS[0, 1]
show slow_rate
show fast_rate

# ten steps of 0.1 take the system from t = 0 to t = 1
H_SYS = 0.1
N_SYS = 10
# 12 steps of 0.05 take y' = -50 y from t = 0 to t = 0.6
H = 0.05
NSTEP = 12
y = 1.0
for n to NSTEP {
    y = decay_step(y, H)
}
show y
# lambda h, the number backward Euler divides by: 1 / (1 + lambda h) per step
lambda_h = LAMBDA * H
show lambda_h

test "one step of 0.05 multiplies y by 1 / (1 + 2.5) = 0.285714" {
    assert_near(decay_step(1.0, 0.05), 0.2857142857142857, 1.0e-15)
}
test "twelve steps of 0.05 leave 2.9593e-7: small and positive, never negative" {
    z = 1.0
    for n to NSTEP {
        z = decay_step(z, H)
        assert_gt(z, 0.0)
    }
    assert_near(z, 2.959262343537004e-07, 1.0e-20)
}
test "a step 25 times the forward-Euler limit, h = 1, gives 1/51 = 0.0196" {
    assert_near(decay_step(1.0, 1.0), 0.0196078431372549, 1.0e-15)
}
test "ten steps of 0.1 on the system end at numpy's (0.38554, 0.38554): the fast mode is gone" {
    w = [2.0, 0.0]
    for n to N_SYS {
        w = system_step(w, H_SYS)
    }
    assert_near(w[0], 0.3855432894295282, 1.0e-13)
    assert_near(w[1], 0.38554328942952826, 1.0e-13)
    assert_near(w[0] - w[1], 0.0, 1.0e-13)
}

# SPDX-License-Identifier: MIT OR Apache-2.0
# SPDX-FileCopyrightText: 2026 The Viv authors

#: N_VEC  vectors, each of dimension N_VEC + 1
N_VEC = 10
EPS = 1.0e-8

#| The Läuchli vectors as the rows of an N_VEC by (N_VEC + 1) array: row k is
#| $e_0 + \varepsilon e_{k+1}$.
def lauchli() {
    A = zeros(N_VEC, N_VEC + 1)
    for k to N_VEC {
        A[k, 0] = 1.0
        A[k, k + 1] = EPS
    }
    return A
}

#| Orthonormal rows spanning the same nested subspaces as the rows of A: row k of
#| the result is in the span of rows 0..k of A, with a positive dot product with
#| row k of A. As written it is classical Gram-Schmidt.
def orthonormalize(A: Arr) {
    n = shape(A)[0]
    d = shape(A)[1]
    Q = zeros(n, d)
    for k to n {
        a = zeros(d)
        for i to d {
            a[i] = A[k, i]
        }
        dots = zeros(n)
        for j to k {
            s = 0.0
            for i to d {
                s = s + Q[j, i] * A[k, i]
            }
            dots[j] = s
        }
        for j to k {
            for i to d {
                a[i] = a[i] - dots[j] * Q[j, i]
            }
        }
        nr = sqrt(sum(a * a))
        for i to d {
            Q[k, i] = a[i] / nr
        }
    }
    return Q
}

#| The largest $|q_i \cdot q_j - \delta_{ij}|$ over the rows of Q.
def loss_of_orthogonality(Q: Arr) {
    n = shape(Q)[0]
    d = shape(Q)[1]
    worst = 0.0
    for p to n {
        for q to n {
            s = 0.0
            for i to d {
                s = s + Q[p, i] * Q[q, i]
            }
            if p == q {
                s = s - 1.0
            }
            worst = max(worst, abs(s))
        }
    }
    return worst
}

A = lauchli()
Q = orthonormalize(A)
show loss_of_orthogonality(Q)
# the angle, in degrees, between the two rows whose dot product is largest
worst_angle = acos(loss_of_orthogonality(Q)) * 180.0 / acos(-1.0)
show worst_angle

test "the rows are orthonormal to 1e-15 (classical Gram-Schmidt gives 0.5, modified 7.1e-9)" {
    assert_lt(loss_of_orthogonality(orthonormalize(lauchli())), 1.0e-15)
}
test "the second vector is mpmath's (7.07e-9, -1/sqrt 2, 1/sqrt 2, 0, ...)" {
    Q = orthonormalize(lauchli())
    assert_near(Q[1, 0], 7.0710678118654749e-9, 1.0e-12)
    assert_near(Q[1, 1], -0.70710678118654747, 1.0e-12)
    assert_near(Q[1, 2], 0.70710678118654754, 1.0e-12)
    assert_near(Q[1, 3], 0.0, 1.0e-12)
}
test "the last vector is mpmath's (1.05e-9, -0.10541 nine times, 0.94868)" {
    Q = orthonormalize(lauchli())
    assert_near(Q[N_VEC - 1, 0], 1.0540925533894598e-9, 1.0e-12)
    for i from 1 to N_VEC {
        assert_near(Q[N_VEC - 1, i], -0.10540925533894598, 1.0e-12)
    }
    assert_near(Q[N_VEC - 1, N_VEC], 0.9486832980505138, 1.0e-12)
}
test "each input row is rebuilt from the rows before it: a_k = sum over j <= k of (q_j . a_k) q_j" {
    A = lauchli()
    Q = orthonormalize(A)
    for k to N_VEC {
        for i to N_VEC + 1 {
            r = A[k, i]
            for j from 0 to k + 1 {
                c = 0.0
                for m to N_VEC + 1 {
                    c = c + Q[j, m] * A[k, m]
                }
                r = r - c * Q[j, i]
            }
            assert_near(r, 0.0, 1.0e-15)
        }
    }
}

# SPDX-License-Identifier: MIT OR Apache-2.0
# SPDX-FileCopyrightText: 2026 The Viv authors

#| The decaying solution of $y'' = y$ at $x_i = ih$, $i = 0, \ldots, m$, with $y_0 = 1$.
#| As written it runs Numerov outward from $y_0 = 1$, $y_1 = e^{-h}$.
def decaying(m, h) {
    c = 1.0 - h * h / 12.0
    d = 1.0 + 5.0 * h * h / 12.0
    y = zeros(m + 1)
    y[0] = 1.0
    y[1] = exp(-h)
    for i from 1 to m {
        y[i + 1] = (2.0 * d * y[i] - c * y[i - 1]) / c
    }
    return y
}

#| The largest relative difference between y and $e^{-x}$ on the grid of spacing h.
def max_rel_error(y: Arr, h) {
    e = 0.0
    for i to len(y) {
        e = max(e, abs(y[i] / exp(-i * h) - 1.0))
    }
    return e
}

M_SHORT = 60
M_LONG = 120
H = 0.15
H_HALF = 0.075
err_short = max_rel_error(decaying(M_SHORT, H), H)
show err_short
# each test's bound over the reference's error on the same grid
tolerance_margin = [1.3e-5 / 8.873863e-6, 8.0e-7 / 5.576447e-7, 2.7e-5 / 1.835749e-5]
show tolerance_margin

test "y(0) = 1" {
    assert_near(decaying(M_SHORT, H)[0], 1.0, 1.0e-15)
}
test "with h = 0.15 on [0, 9] every point is within 1.3e-5 of e^(-x), where numpy's inward run reaches 8.87e-6" {
    assert_lt(max_rel_error(decaying(M_SHORT, H), H), 1.3e-5)
}
test "with h = 0.075 on [0, 9] every point is within 8e-7, where numpy reaches 5.58e-7" {
    assert_lt(max_rel_error(decaying(M_LONG, H_HALF), H_HALF), 8.0e-7)
}
test "with h = 0.15 on [0, 18], where outward is off by 2e9, every point is within 2.7e-5 (numpy reaches 1.84e-5)" {
    assert_lt(max_rel_error(decaying(M_LONG, H), H), 2.7e-5)
}
test "halving h divides the error by 12 to 20, as a fourth-order method's should (numpy: 15.9)" {
    ratio = max_rel_error(decaying(M_SHORT, H), H) / max_rel_error(decaying(M_LONG, H_HALF), H_HALF)
    assert_gt(ratio, 12.0)
    assert_lt(ratio, 20.0)
}

# SPDX-License-Identifier: MIT OR Apache-2.0
# SPDX-FileCopyrightText: 2026 The Viv authors

A_TIE = [[0.0, 2.0], [2.0, 0.0]]
B_TIE = [[1.0, 2.0], [2.0, -1.0]]
ITERS = 60

#| The unit vector power iteration with $A + sI$ reaches after `iters` steps from
#| $(1, 0.3)$, signed so its first entry is positive. As written it ignores the
#| shift $s$.
def shifted_power(A: Arr, s, iters) {
    v = [1.0, 0.3]
    for k to iters {
        w = zeros(2)
        for i to 2 {
            w[i] = A[i, 0] * v[0] + A[i, 1] * v[1]
        }
        v = w / sqrt(w[0] * w[0] + w[1] * w[1])
    }
    if v[0] < 0.0 {
        v = -v
    }
    return v
}

#| The Rayleigh quotient $v^{\mathsf T} A v$ of a unit vector v.
def rayleigh(A: Arr, v: Arr) {
    q = 0.0
    for i to 2 {
        for j to 2 {
            q = q + v[i] * A[i, j] * v[j]
        }
    }
    return q
}

v_plain = shifted_power(A_TIE, 0.0, ITERS)
show v_plain
show rayleigh(A_TIE, v_plain)
# the eigenvalues 2 + s and -2 + s of A_TIE + sI, for s = 1 and then s = -1
tie_shift = 1.0
shifted_eigs = [A_TIE[0, 1] + tie_shift, -A_TIE[0, 1] + tie_shift, A_TIE[0, 1] - tie_shift, -A_TIE[0, 1] - tie_shift]
show shifted_eigs

test "shift +1 finds eigenvalue 2, vector (1, 1) / sqrt 2" {
    v = shifted_power(A_TIE, 1.0, ITERS)
    assert_near(v[0], 0.7071067811865475, 1.0e-12)
    assert_near(v[1], 0.7071067811865475, 1.0e-12)
    assert_near(rayleigh(A_TIE, v), 2.0, 1.0e-12)
}
test "shift -1 finds eigenvalue -2, vector (1, -1) / sqrt 2" {
    v = shifted_power(A_TIE, -1.0, ITERS)
    assert_near(v[0], 0.7071067811865475, 1.0e-12)
    assert_near(v[1], -0.7071067811865475, 1.0e-12)
    assert_near(rayleigh(A_TIE, v), -2.0, 1.0e-12)
}
test "on [[1, 2], [2, -1]] shift +1 finds sqrt 5 = 2.2360680 with numpy's vector" {
    v = shifted_power(B_TIE, 1.0, ITERS)
    assert_near(v[0], 0.8506508083520399, 1.0e-12)
    assert_near(v[1], 0.5257311121191335, 1.0e-12)
    assert_near(rayleigh(B_TIE, v), 2.23606797749979, 1.0e-12)
}
test "and shift -1 finds -sqrt 5" {
    v = shifted_power(B_TIE, -1.0, ITERS)
    assert_near(v[0], 0.5257311121191335, 1.0e-12)
    assert_near(v[1], -0.8506508083520399, 1.0e-12)
    assert_near(rayleigh(B_TIE, v), -2.23606797749979, 1.0e-12)
