WIDTH = 4

# rung 1. NAND, and the three gates wired from it

#| $\overline{ab}$.
def nand(a, b) {
    return bxor(band(a, b), 1.0)
}
#| $\bar a$: a NAND with both inputs tied together.
def gate_not(a) {
    return nand(a, a)
}
#| $ab$: a NAND with the bar taken off again.
def gate_and(a, b) {
    return gate_not(nand(a, b))
}
#| $a + b = \overline{\bar a \bar b}$: a NAND of the two inverses.
def gate_or(a, b) {
    return nand(gate_not(a), gate_not(b))
}

show nand(0.0, 0.0)
show nand(1.0, 1.0)

test "NAND is the AND of its inputs, inverted, in all four rows" {
    assert_near(nand(0.0, 0.0), 1.0, 0.0)
    assert_near(nand(0.0, 1.0), 1.0, 0.0)
    assert_near(nand(1.0, 0.0), 1.0, 0.0)
    assert_near(nand(1.0, 1.0), 0.0, 0.0)
}
test "NOT, AND and OR built from NAND agree with the operations they name" {
    assert_near(gate_not(0.0), 1.0, 0.0)
    assert_near(gate_not(1.0), 0.0, 0.0)
    for a to 2 {
        for b to 2 {
            assert_near(gate_and(a, b), band(a, b), 0.0)
            assert_near(gate_or(a, b), bor(a, b), 0.0)
        }
    }
}

