test "XOR is on exactly when the two bits differ" {
    assert_near(gate_xor(0.0, 0.0), 0.0, 0.0)
    assert_near(gate_xor(0.0, 1.0), 1.0, 0.0)
    assert_near(gate_xor(1.0, 0.0), 1.0, 0.0)
    assert_near(gate_xor(1.0, 1.0), 0.0, 0.0)
}

